(context) => {
  if (!context || typeof context !== 'object') return undefined;
  const o = context.observation;
  if (!o || typeof o !== 'object' || !o.me || typeof o.me !== 'object') return undefined;
  const me = o.me;
  if (typeof me.x !== 'number' || typeof me.y !== 'number') return undefined;
  const asList = (v) => (Array.isArray(v) ? v : []);
  if (asList(o.parcels).length > 0) return undefined;
  if (asList(o.keys).length > 0) return undefined;
  if (asList(o.doors).length > 0) return undefined;
  if (asList(o.batteries).length > 0) return undefined;
  if (typeof o.energy === 'number' && o.energy <= 0) return undefined;
  const tiles = asList(o.tiles);
  const known = {};
  for (let i = 0; i < tiles.length; i++) {
    const t = tiles[i];
    if (t && typeof t === 'object' && typeof t.x === 'number' && typeof t.y === 'number') known[t.x + ',' + t.y] = true;
  }
  const W = o.width;
  const H = o.height;
  const inBounds = (x, y) => (typeof W !== 'number' || (x >= 0 && x < W)) && (typeof H !== 'number' || (y >= 0 && y < H));
  const DIRS = [{ name: 'up', dx: 0, dy: -1 }, { name: 'right', dx: 1, dy: 0 }, { name: 'down', dx: 0, dy: 1 }, { name: 'left', dx: -1, dy: 0 }];
  const memory = Array.isArray(context.memory) ? context.memory : [];
  const visits = {};
  const rejected = {};
  for (let i = 0; i < memory.length; i++) {
    const m = memory[i];
    if (!m || typeof m !== 'object' || typeof m.x !== 'number' || typeof m.y !== 'number') continue;
    const key = m.x + ',' + m.y;
    visits[key] = (visits[key] || 0) + 1;
    let kind = null;
    let dir = null;
    if (m.action && typeof m.action === 'object') { kind = m.action.kind; dir = m.action.direction; }
    else if (typeof m.action === 'string' && m.action.indexOf(':') > 0) { const parts = m.action.split(':'); kind = parts[0]; dir = parts[1]; }
    if (m.accepted === false && kind) rejected[key + ':' + kind + (dir ? ':' + dir : '')] = true;
    if (m.accepted !== false && kind === 'move' && dir) {
      for (let d = 0; d < DIRS.length; d++) {
        if (DIRS[d].name === dir) { const dk = (m.x + DIRS[d].dx) + ',' + (m.y + DIRS[d].dy); visits[dk] = (visits[dk] || 0) + 1; break; }
      }
    }
  }
  const visitCount = (x, y) => visits[x + ',' + y] || 0;
  const knownNeighbors = [];
  const speculative = [];
  for (let i = 0; i < DIRS.length; i++) {
    const d = DIRS[i];
    const nx = me.x + d.dx;
    const ny = me.y + d.dy;
    const e = { name: d.name, nx: nx, ny: ny };
    if (known[nx + ',' + ny]) knownNeighbors.push(e);
    else if (inBounds(nx, ny)) speculative.push(e);
  }
  if (knownNeighbors.length > 0) {
    const unvisited = [];
    for (let i = 0; i < knownNeighbors.length; i++) {
      if (visitCount(knownNeighbors[i].nx, knownNeighbors[i].ny) === 0) unvisited.push(knownNeighbors[i]);
    }
    const pool = unvisited.length > 0 ? unvisited : knownNeighbors;
    let best = pool[0];
    for (let i = 1; i < pool.length; i++) {
      if (visitCount(pool[i].nx, pool[i].ny) < visitCount(best.nx, best.ny)) best = pool[i];
    }
    const unexplored = unvisited.length > 0;
    return {
      action: { kind: 'move', direction: best.name },
      confidence: unexplored ? 0.8 : 0.7,
      rationale: unexplored ? 'Known unvisited neighbor ' + best.name + ' on the locally observed tile graph; expanding the frontier along known tiles.' : 'All known neighbors are visited; backtracking through the least-visited known neighbor ' + best.name + ' instead of speculating out of the graph.'
    };
  }
  const candidates = [];
  for (let i = 0; i < speculative.length; i++) {
    const e = speculative[i];
    if (!rejected[me.x + ',' + me.y + ':move:' + e.name] && visitCount(e.nx, e.ny) === 0) candidates.push(e);
  }
  if (candidates.length > 0) {
    return {
      action: { kind: 'move', direction: candidates[0].name },
      confidence: 0.5,
      rationale: 'No known neighbor exists yet; speculating within width/height bounds along ' + candidates[0].name + ', skipping directions rejected from this position.'
    };
  }
  return undefined;
}
